namespace FOC.Application.Save
{
    public sealed class CampaignSaveValidator : IInvariantValidator<CampaignSaveData>
    {
        public ValidationResult Validate(CampaignSaveData subject)
        {
            var result = new ValidationResult();
            if (subject == null)
            {
                result.AddError("SAVE_NULL", "Campaign save data is required.");
                return result;
            }

            if (subject.SaveVersion <= 0)
            {
                result.AddError("SAVE_VERSION_INVALID", "SaveVersion must be positive.");
            }

            else if (subject.SaveVersion > CampaignSaveData.CurrentSaveVersion)
            {
                result.AddError("SAVE_VERSION_FUTURE", "SaveVersion is newer than this game can read.");
            }

            if (subject.Characters == null)
            {
                result.AddError("CHARACTERS_NULL", "Characters collection is required.");
            }

            if (subject.CharacterRelations == null)
            {
                result.AddError("CHARACTER_RELATIONS_NULL", "Character relations collection is required.");
            }

            if (subject.Organizations == null || subject.Houses == null || subject.Cliques == null)
            {
                result.AddError("SOCIAL_COLLECTION_NULL", "Organization, House and Clique collections are required.");
            }
            if (subject.Religions == null || subject.Sects == null || subject.CharacterReligions == null || subject.ReligionProfiles == null || subject.ReligionPolicies == null || subject.ReligiousCliqueAssociations == null)
            {
                result.AddError("RELIGION_COLLECTION_NULL", "Religion collections are required.");
            }
            if(subject.Cities==null)result.AddError("CITY_COLLECTION_NULL","City collection is required.");
            if(subject.TradeGoods==null||subject.ProductionRecipes==null||subject.CityMarkets==null||subject.Caravans==null)result.AddError("ECONOMY_COLLECTION_NULL","Economy collections are required.");
            if(subject.DiplomaticActors==null||subject.DiplomaticRelations==null||subject.EnvoyMissions==null||subject.DiplomaticMessages==null||subject.DiplomaticActions==null||subject.Reports==null||subject.ActorInformation==null||subject.DiplomaticAgreements==null)result.AddError("DIPLOMACY_COLLECTION_NULL","Diplomacy collections are required.");
            if(subject.Armies==null||subject.RecruitmentSources==null||subject.RecruitmentRecords==null)result.AddError("MILITARY_COLLECTION_NULL","Military collections are required.");
            if(subject.TroopDefinitions==null||subject.WeaponDefinitions==null||subject.ArmorDefinitions==null||subject.ShieldDefinitions==null||subject.MountDefinitions==null||subject.AuxiliaryEquipmentDefinitions==null||subject.EquipmentInstances==null||subject.Soldiers==null)result.AddError("SOLDIER_COLLECTION_NULL","Soldier and equipment collections are required.");
            if(subject.Battles==null)result.AddError("BATTLE_COLLECTION_NULL","Battle collection is required.");
            if(subject.Encounters==null||subject.Contracts==null)result.AddError("ENCOUNTER_CONTRACT_COLLECTION_NULL","Encounter and Contract collections are required.");

            if (subject.Characters != null && subject.CharacterRelations != null)
            {
                ValidateCharacters(subject, result);
                if (subject.Organizations != null && subject.Houses != null && subject.Cliques != null) ValidateSocial(subject, result);
                if (subject.Religions != null && subject.Sects != null && subject.CharacterReligions != null && subject.ReligionProfiles != null && subject.ReligionPolicies != null && subject.ReligiousCliqueAssociations != null) ValidateReligion(subject, result);
                if(subject.Cities!=null&&subject.Organizations!=null)ValidateCities(subject,result);
                if(subject.TradeGoods!=null&&subject.ProductionRecipes!=null&&subject.CityMarkets!=null&&subject.Caravans!=null&&subject.Cities!=null&&subject.Organizations!=null&&subject.Houses!=null)ValidateEconomy(subject,result);
                if(subject.DiplomaticActors!=null&&subject.DiplomaticRelations!=null&&subject.EnvoyMissions!=null&&subject.DiplomaticMessages!=null&&subject.DiplomaticActions!=null&&subject.Reports!=null&&subject.ActorInformation!=null&&subject.DiplomaticAgreements!=null)ValidateDiplomacy(subject,result);
                if(subject.Armies!=null&&subject.RecruitmentSources!=null&&subject.RecruitmentRecords!=null&&subject.Cities!=null&&subject.CityMarkets!=null&&subject.Caravans!=null&&subject.TradeGoods!=null&&subject.Organizations!=null&&subject.DiplomaticActors!=null)ValidateMilitary(subject,result);
                if(subject.TroopDefinitions!=null&&subject.WeaponDefinitions!=null&&subject.ArmorDefinitions!=null&&subject.ShieldDefinitions!=null&&subject.MountDefinitions!=null&&subject.AuxiliaryEquipmentDefinitions!=null&&subject.EquipmentInstances!=null&&subject.Soldiers!=null&&subject.Armies!=null&&subject.RecruitmentRecords!=null&&subject.TradeGoods!=null&&subject.Cities!=null)ValidateSoldiers(subject,result);
                if(subject.Battles!=null&&subject.Armies!=null&&subject.Soldiers!=null&&subject.EquipmentInstances!=null)ValidateBattles(subject,result);
                if(subject.Encounters!=null&&subject.Contracts!=null)ValidateEncounterContracts(subject,result);
            }

            if (string.IsNullOrWhiteSpace(subject.CampaignId))
            {
                result.AddError("CAMPAIGN_ID_INVALID", "CampaignId is required.");
            }

            if (string.IsNullOrWhiteSpace(subject.GameVersion))
            {
                result.AddError("GAME_VERSION_INVALID", "GameVersion is required.");
            }

            if (string.IsNullOrWhiteSpace(subject.ContentDataVersion))
            {
                result.AddError("CONTENT_VERSION_INVALID", "ContentDataVersion is required.");
            }

            if (subject.WorldGenRevision < 0)
            {
                result.AddError("WORLD_GEN_REVISION_INVALID", "WorldGenRevision cannot be negative.");
            }

            if (subject.WorldTime < 0)
            {
                result.AddError("WORLD_TIME_INVALID", "WorldTime cannot be negative.");
            }

            if (subject.RngState == 0)
            {
                result.AddError("RNG_STATE_INVALID", "RngState cannot be zero.");
            }

            return result;
        }

        private static void ValidateBattles(CampaignSaveData s,ValidationResult r)
        {
            var armies=new Dictionary<string,ArmySaveData>(StringComparer.Ordinal);var units=new Dictionary<string,UnitGroupSaveData>(StringComparer.Ordinal);foreach(var a in s.Armies){if(a==null)continue;armies[a.ArmyId]=a;foreach(var u in a.Units)if(u!=null)units[u.UnitGroupId]=u;}var soldiers=new Dictionary<string,SoldierSaveData>(StringComparer.Ordinal);foreach(var soldier in s.Soldiers)if(soldier!=null&&!soldiers.ContainsKey(soldier.SoldierId))soldiers.Add(soldier.SoldierId,soldier);var equipment=new HashSet<string>(s.EquipmentInstances.Where(x=>x!=null).Select(x=>x.EquipmentInstanceId),StringComparer.Ordinal);var battleIds=new HashSet<string>(StringComparer.Ordinal);
            foreach(var b in s.Battles)
            {
                if(b==null||string.IsNullOrWhiteSpace(b.BattleId)||!battleIds.Add(b.BattleId)||b.StartedAt<0||b.Step<0||b.RngState==0||!Enum.IsDefined(typeof(BattleLifecycle),b.Lifecycle)||b.Sides==null||b.Sectors==null||b.Deployments==null||b.Orders==null||b.Events==null||b.Ammunition==null){r.AddError("BATTLE_INVALID","Battle identity, lifecycle, RNG or collections are invalid.");continue;}if(b.Sides.Count<2)r.AddError("BATTLE_SIDES_INVALID","Battle requires at least two sides.");var sideIds=new HashSet<string>(StringComparer.Ordinal);var participatingArmies=new HashSet<string>(StringComparer.Ordinal);var participatingUnits=new HashSet<string>(StringComparer.Ordinal);var participatingSoldiers=new HashSet<string>(StringComparer.Ordinal);foreach(var side in b.Sides){if(side==null||string.IsNullOrWhiteSpace(side.SideId)||!sideIds.Add(side.SideId)||string.IsNullOrWhiteSpace(side.CommanderCharacterId)||side.Participants==null||side.Participants.Count==0){r.AddError("BATTLE_SIDE_INVALID","Battle side is invalid.");continue;}foreach(var p in side.Participants){if(p==null||!armies.ContainsKey(p.ArmyId)||!participatingArmies.Add(p.ArmyId)||string.IsNullOrWhiteSpace(p.CommanderCharacterId)||p.Units==null||p.Supply==null){r.AddError("BATTLE_PARTICIPANT_INVALID","Battle participant is invalid.");continue;}foreach(var u in p.Units){if(u==null||!units.ContainsKey(u.UnitGroupId)||!StringComparer.Ordinal.Equals(u.ArmyId,p.ArmyId)||!participatingUnits.Add(u.UnitGroupId)||u.CampaignHeadcount<0||!Enum.IsDefined(typeof(MoraleAssessment),u.Morale)||!Enum.IsDefined(typeof(FatigueAssessment),u.Fatigue)||!Enum.IsDefined(typeof(DisciplineAssessment),u.Discipline)||u.Combatants==null){r.AddError("BATTLE_UNIT_SNAPSHOT_INVALID","Battle Unit snapshot is invalid.");continue;}if(u.Combatants.Count>u.CampaignHeadcount)r.AddError("BATTLE_FAKE_SOLDIER_EXPANSION","Battle combatants exceed campaign headcount.");foreach(var c in u.Combatants){if(c==null||!soldiers.TryGetValue(c.SoldierId,out var soldier)||!participatingSoldiers.Add(c.SoldierId)||!StringComparer.Ordinal.Equals(c.UnitGroupId,u.UnitGroupId)||!StringComparer.Ordinal.Equals(c.TroopDefinitionId,soldier.TroopDefinitionId)||string.IsNullOrWhiteSpace(c.CombatRoleId)||c.EquipmentInstanceIds==null||c.EquipmentInstanceIds.Distinct(StringComparer.Ordinal).Count()!=c.EquipmentInstanceIds.Count||c.EquipmentInstanceIds.Any(id=>!equipment.Contains(id))){r.AddError("BATTLE_COMBATANT_SNAPSHOT_INVALID","Battle combatant or persistent equipment snapshot is invalid.");continue;}var live=soldier.Weapons.Select(x=>x.EquipmentInstanceId).Concat(soldier.Armor.Select(x=>x.EquipmentInstanceId));if(!string.IsNullOrEmpty(soldier.ShieldEquipmentId))live=live.Concat(new[]{soldier.ShieldEquipmentId});if(!string.IsNullOrEmpty(soldier.MountEquipmentId))live=live.Concat(new[]{soldier.MountEquipmentId});if(!live.OrderBy(x=>x,StringComparer.Ordinal).SequenceEqual(c.EquipmentInstanceIds.OrderBy(x=>x,StringComparer.Ordinal),StringComparer.Ordinal))r.AddError("BATTLE_LOADOUT_REROLL","Battle snapshot differs from persistent Soldier loadout.");}}}}var sectors=new Dictionary<string,BattleSectorSaveData>(StringComparer.Ordinal);foreach(var x in b.Sectors){if(x==null||string.IsNullOrWhiteSpace(x.SectorId)||sectors.ContainsKey(x.SectorId)||x.Terrain==null||x.Terrain.Any(v=>!Enum.IsDefined(typeof(BattleTerrainTag),v))||x.Terrain.Distinct().Count()!=x.Terrain.Count||x.EligibleSideIds==null||x.EligibleSideIds.Any(id=>!sideIds.Contains(id))||x.AdjacentSectorIds==null){r.AddError("BATTLE_SECTOR_INVALID","Battle sector is invalid.");continue;}sectors.Add(x.SectorId,x);}foreach(var x in sectors.Values)foreach(var adjacent in x.AdjacentSectorIds)if(StringComparer.Ordinal.Equals(x.SectorId,adjacent)||!sectors.TryGetValue(adjacent,out var other)||!other.AdjacentSectorIds.Contains(x.SectorId,StringComparer.Ordinal))r.AddError("BATTLE_SECTOR_GRAPH_INVALID","Sector adjacency is dangling, self-referential or asymmetric.");var deploymentIds=new HashSet<string>(StringComparer.Ordinal);var deployedUnits=new HashSet<string>(StringComparer.Ordinal);foreach(var x in b.Deployments)if(x==null||string.IsNullOrWhiteSpace(x.DeploymentGroupId)||!deploymentIds.Add(x.DeploymentGroupId)||!deployedUnits.Add(x.UnitGroupId)||!sideIds.Contains(x.SideId)||!participatingArmies.Contains(x.ArmyId)||!participatingUnits.Contains(x.UnitGroupId)||!sectors.ContainsKey(x.SectorId)||!Enum.IsDefined(typeof(BattleFormation),x.Formation))r.AddError("BATTLE_DEPLOYMENT_INVALID","Battle deployment is invalid or duplicated.");var orderIds=new HashSet<string>(StringComparer.Ordinal);var orderSequences=new HashSet<long>();foreach(var x in b.Orders)if(x==null||string.IsNullOrWhiteSpace(x.BattleOrderId)||!orderIds.Add(x.BattleOrderId)||x.Sequence<0||!orderSequences.Add(x.Sequence)||!Enum.IsDefined(typeof(BattleOrderKind),x.Kind)||!sideIds.Contains(x.SideId)||!deploymentIds.Contains(x.DeploymentGroupId)||(!string.IsNullOrEmpty(x.TargetSectorId)&&!sectors.ContainsKey(x.TargetSectorId))||(!string.IsNullOrEmpty(x.TargetGroupId)&&!deploymentIds.Contains(x.TargetGroupId)))r.AddError("BATTLE_ORDER_INVALID","Battle order is invalid.");var eventIds=new HashSet<string>(StringComparer.Ordinal);var eventSequences=new HashSet<long>();foreach(var x in b.Events)if(x==null||string.IsNullOrWhiteSpace(x.BattleEventId)||!eventIds.Add(x.BattleEventId)||x.Sequence<0||!eventSequences.Add(x.Sequence)||!participatingSoldiers.Contains(x.TargetSoldierId)||!Enum.IsDefined(typeof(BattleCasualtyOutcome),x.Outcome))r.AddError("BATTLE_EVENT_INVALID","Battle event is invalid.");var ammoKeys=new HashSet<string>(StringComparer.Ordinal);foreach(var x in b.Ammunition)if(x==null||!participatingSoldiers.Contains(x.SoldierId)||string.IsNullOrWhiteSpace(x.AmmoFamilyId)||x.Quantity<0||!ammoKeys.Add(x.SoldierId+"\n"+x.AmmoFamilyId))r.AddError("BATTLE_AMMO_INVALID","Battle ammunition allocation is invalid.");if((b.Lifecycle==(int)BattleLifecycle.Completed)!= (b.Result!=null))r.AddError("BATTLE_RESULT_LIFECYCLE_INVALID","Completed lifecycle and BattleResult must agree.");if(b.IsReconciled&&(b.Lifecycle!=(int)BattleLifecycle.Completed||b.Result==null))r.AddError("BATTLE_RECONCILIATION_STATE_INVALID","Only a completed result can be reconciled.");if(b.Result!=null)ValidateBattleResult(b,b.Result,sideIds,participatingUnits,participatingSoldiers,r);
            }
        }
        private static void ValidateBattleResult(BattleSaveData b,BattleResultSaveData x,HashSet<string> sides,HashSet<string> units,HashSet<string> soldiers,ValidationResult r){if(!Enum.IsDefined(typeof(BattleEndReason),x.EndReason)||x.CompletedAt<b.StartedAt||x.ElapsedSteps<0||(!string.IsNullOrEmpty(x.WinningSideId)&&!sides.Contains(x.WinningSideId))||x.ParticipatingSideIds==null||x.Units==null||x.Soldiers==null||x.Characters==null||x.Ammunition==null){r.AddError("BATTLE_RESULT_INVALID","BattleResult is invalid.");return;}if(x.ParticipatingSideIds.Count!=sides.Count||!new HashSet<string>(x.ParticipatingSideIds,StringComparer.Ordinal).SetEquals(sides))r.AddError("BATTLE_RESULT_SIDES_INVALID","BattleResult participating sides do not match the battle snapshot.");var u=new HashSet<string>(StringComparer.Ordinal);foreach(var q in x.Units)if(q==null||!units.Contains(q.UnitGroupId)||!u.Add(q.UnitGroupId)||q.AggregateLosses<0||!Enum.IsDefined(typeof(MoraleAssessment),q.Morale)||!Enum.IsDefined(typeof(FatigueAssessment),q.Fatigue)||!Enum.IsDefined(typeof(DisciplineAssessment),q.Discipline))r.AddError("BATTLE_UNIT_OUTCOME_INVALID","Unit outcome is invalid.");var s=new HashSet<string>(StringComparer.Ordinal);foreach(var q in x.Soldiers)if(q==null||!soldiers.Contains(q.SoldierId)||!s.Add(q.SoldierId)||!Enum.IsDefined(typeof(BattleCasualtyOutcome),q.Outcome))r.AddError("BATTLE_SOLDIER_OUTCOME_INVALID","Soldier outcome is invalid.");var c=new HashSet<string>(StringComparer.Ordinal);foreach(var q in x.Characters)if(q==null||string.IsNullOrWhiteSpace(q.CharacterId)||!c.Add(q.CharacterId)||!Enum.IsDefined(typeof(BattleCasualtyOutcome),q.Outcome)||(q.Outcome==(int)BattleCasualtyOutcome.Wounded)!=q.InjurySeverity.HasValue||(q.Outcome==(int)BattleCasualtyOutcome.Captured)!=( !string.IsNullOrEmpty(q.CaptorCharacterId)&&!string.IsNullOrEmpty(q.CaptorArmyId)))r.AddError("BATTLE_CHARACTER_OUTCOME_INVALID","Character outcome is invalid.");var expected=b.Ammunition.Select(q=>q.SoldierId+"\n"+q.AmmoFamilyId+"\n"+q.Quantity).OrderBy(q=>q,StringComparer.Ordinal).ToList();var actual=x.Ammunition.Select(q=>q==null?string.Empty:q.SoldierId+"\n"+q.AmmoFamilyId+"\n"+q.RemainingQuantity).OrderBy(q=>q,StringComparer.Ordinal).ToList();if(x.Ammunition.Any(q=>q==null||!soldiers.Contains(q.SoldierId)||string.IsNullOrWhiteSpace(q.AmmoFamilyId)||q.RemainingQuantity<0)||!actual.SequenceEqual(expected,StringComparer.Ordinal))r.AddError("BATTLE_AMMO_OUTCOME_INVALID","BattleResult ammunition outcome does not match terminal battle ammunition state.");}

        private static void ValidateEncounterContracts(CampaignSaveData s,ValidationResult r)
        {
            var characters=new HashSet<string>(s.Characters.Where(x=>x!=null).Select(x=>x.CharacterId),StringComparer.Ordinal);var cities=new HashSet<string>(s.Cities.Where(x=>x!=null).Select(x=>x.CityId),StringComparer.Ordinal);var caravans=new HashSet<string>(s.Caravans.Where(x=>x!=null).Select(x=>x.CaravanId),StringComparer.Ordinal);var factions=new HashSet<string>(s.DiplomaticActors.Where(x=>x!=null).Select(x=>x.FactionId),StringComparer.Ordinal);var armies=new HashSet<string>(s.Armies.Where(x=>x!=null).Select(x=>x.ArmyId),StringComparer.Ordinal);var cliques=new HashSet<string>(s.Cliques.Where(x=>x!=null).Select(x=>x.CliqueId),StringComparer.Ordinal);var organizations=new HashSet<string>(s.Organizations.Where(x=>x!=null).Select(x=>x.OrganizationId),StringComparer.Ordinal);var battles=new HashSet<string>(s.Battles.Where(x=>x!=null).Select(x=>x.BattleId),StringComparer.Ordinal);
            var encounterIds=new HashSet<string>(StringComparer.Ordinal);foreach(var x in s.Encounters){if(x==null||string.IsNullOrWhiteSpace(x.EncounterId)||!encounterIds.Add(x.EncounterId)||string.IsNullOrWhiteSpace(x.DefinitionId)||!EncounterAuthority.Matches((EncounterFamily)x.Family,(EncounterType)x.Type)||x.CreatedAt<0||x.RngState==0||!Enum.IsDefined(typeof(EncounterLifecycle),x.Lifecycle)||x.Participants==null||x.Participants.Count==0||!SavedEncounterRefValid(x.SourceKind,x.SourceId,characters,cities,caravans,factions,armies,battles)){r.AddError("ENCOUNTER_INVALID","Encounter identity, definition, context, RNG or lifecycle is invalid.");continue;}var refs=new HashSet<string>(StringComparer.Ordinal);foreach(var p in x.Participants)if(p==null||!SavedEncounterRefValid(p.Kind,p.Id,characters,cities,caravans,factions,armies,battles)||!refs.Add(p.Kind+"\n"+p.Id))r.AddError("ENCOUNTER_PARTICIPANT_INVALID","Encounter participant is invalid or duplicated.");var lifecycle=(EncounterLifecycle)x.Lifecycle;if(lifecycle==EncounterLifecycle.Available&&(x.EngagedAt.HasValue||!string.IsNullOrEmpty(x.SelectedChoiceId)||x.Resolution!=null||x.OutcomeApplied)||lifecycle==EncounterLifecycle.Engaged&&(!x.EngagedAt.HasValue||!string.IsNullOrEmpty(x.SelectedChoiceId)||x.Resolution!=null||x.OutcomeApplied)||lifecycle==EncounterLifecycle.Resolved&&(!x.EngagedAt.HasValue||string.IsNullOrWhiteSpace(x.SelectedChoiceId)||x.Resolution==null)||lifecycle==EncounterLifecycle.Cancelled&&(x.Resolution!=null||x.OutcomeApplied))r.AddError("ENCOUNTER_LIFECYCLE_INVALID","Encounter lifecycle and resolution disagree.");if(x.Resolution!=null&&(string.IsNullOrWhiteSpace(x.Resolution.OutcomeId)||string.IsNullOrWhiteSpace(x.Resolution.PolicyId)||!StringComparer.Ordinal.Equals(x.Resolution.SelectedChoiceId,x.SelectedChoiceId)||x.Resolution.ResolvedAt<x.CreatedAt||x.Resolution.RngState==0))r.AddError("ENCOUNTER_RESOLUTION_INVALID","Encounter resolution is invalid.");}
            var contractIds=new HashSet<string>(StringComparer.Ordinal);foreach(var x in s.Contracts){if(x==null||string.IsNullOrWhiteSpace(x.ContractId)||!contractIds.Add(x.ContractId)||string.IsNullOrWhiteSpace(x.DefinitionId)||!Enum.IsDefined(typeof(ContractCategory),x.Category)||!Enum.IsDefined(typeof(ContractIssuerKind),x.IssuerKind)||!SavedIssuerValid(x.IssuerKind,x.IssuerId,characters,cities,factions,cliques,organizations)||x.Targets==null||x.Objectives==null||x.Objectives.Count==0||x.OfferedAt<0||!Enum.IsDefined(typeof(ContractLifecycle),x.Lifecycle)){r.AddError("CONTRACT_INVALID","Contract identity, definition, issuer or lifecycle is invalid.");continue;}if(!string.IsNullOrEmpty(x.AssigneeCharacterId)&&!characters.Contains(x.AssigneeCharacterId))r.AddError("CONTRACT_ASSIGNEE_INVALID","Contract assignee is dangling.");var slots=new HashSet<string>(StringComparer.Ordinal);foreach(var t in x.Targets)if(t==null||string.IsNullOrWhiteSpace(t.SlotId)||!slots.Add(t.SlotId)||!SavedTargetValid(t.Kind,t.TargetId,characters,cities,caravans,factions,cliques,armies,battles,encounterIds))r.AddError("CONTRACT_TARGET_INVALID","Contract target is invalid or duplicated.");var objectives=new HashSet<string>(StringComparer.Ordinal);foreach(var o in x.Objectives){if(o==null||string.IsNullOrWhiteSpace(o.ObjectiveId)||!objectives.Add(o.ObjectiveId)||!Enum.IsDefined(typeof(ContractEvidenceKind),o.EvidenceKind)||o.RequiredEvidenceCount<=0||o.Evidence==null||(!string.IsNullOrEmpty(o.TargetSlotId)&&!slots.Contains(o.TargetSlotId))){r.AddError("CONTRACT_OBJECTIVE_INVALID","Contract objective is invalid or duplicated.");continue;}var evidence=new HashSet<string>(StringComparer.Ordinal);foreach(var e in o.Evidence)if(e==null||string.IsNullOrWhiteSpace(e.EvidenceId)||!evidence.Add(e.EvidenceId)||e.Kind!=o.EvidenceKind||!SavedTargetValid(e.TargetKind,e.TargetId,characters,cities,caravans,factions,cliques,armies,battles,encounterIds)||e.OccurredAt<0)r.AddError("CONTRACT_EVIDENCE_INVALID","Contract evidence is invalid or duplicated.");}var lifecycle=(ContractLifecycle)x.Lifecycle;var satisfied=x.Objectives.All(o=>o!=null&&o.Evidence!=null&&o.Evidence.Count>=o.RequiredEvidenceCount);if(lifecycle==ContractLifecycle.Offered&&(x.AcceptedAt.HasValue||x.TerminalAt.HasValue||x.OutcomeApplied)||lifecycle==ContractLifecycle.Active&&(!x.AcceptedAt.HasValue||x.TerminalAt.HasValue||x.OutcomeApplied)||(lifecycle==ContractLifecycle.Completed||lifecycle==ContractLifecycle.Failed)&&(!x.AcceptedAt.HasValue||!x.TerminalAt.HasValue)||lifecycle==ContractLifecycle.Cancelled&&(!x.TerminalAt.HasValue||x.OutcomeApplied)||lifecycle==ContractLifecycle.Completed&&!satisfied)r.AddError("CONTRACT_LIFECYCLE_INVALID","Contract lifecycle, objectives and outcome state disagree.");if(x.Deadline.HasValue&&x.Deadline.Value<=x.OfferedAt)r.AddError("CONTRACT_DEADLINE_INVALID","Contract deadline must be explicit and later than offer time.");}
            foreach(var x in s.Encounters)if(x!=null&&(!string.IsNullOrEmpty(x.LinkedContractId)&&!contractIds.Contains(x.LinkedContractId)||!string.IsNullOrEmpty(x.LinkedBattleId)&&!battles.Contains(x.LinkedBattleId)))r.AddError("ENCOUNTER_LINK_INVALID","Encounter has a dangling Contract or Battle link.");foreach(var x in s.Contracts)if(x!=null&&(!string.IsNullOrEmpty(x.LinkedEncounterId)&&!encounterIds.Contains(x.LinkedEncounterId)||!string.IsNullOrEmpty(x.LinkedBattleId)&&!battles.Contains(x.LinkedBattleId)))r.AddError("CONTRACT_LINK_INVALID","Contract has a dangling Encounter or Battle link.");
        }
        private static bool SavedEncounterRefValid(int kind,string id,HashSet<string> characters,HashSet<string> cities,HashSet<string> caravans,HashSet<string> factions,HashSet<string> armies,HashSet<string> battles){if(!Enum.IsDefined(typeof(EncounterEntityKind),kind)||string.IsNullOrWhiteSpace(id))return false;switch((EncounterEntityKind)kind){case EncounterEntityKind.Character:return characters.Contains(id);case EncounterEntityKind.City:return cities.Contains(id);case EncounterEntityKind.Caravan:return caravans.Contains(id);case EncounterEntityKind.Faction:return factions.Contains(id);case EncounterEntityKind.Army:return armies.Contains(id);case EncounterEntityKind.Battle:return battles.Contains(id);case EncounterEntityKind.Region:return true;default:return false;}}
        private static bool SavedIssuerValid(int kind,string id,HashSet<string> characters,HashSet<string> cities,HashSet<string> factions,HashSet<string> cliques,HashSet<string> organizations){if(!Enum.IsDefined(typeof(ContractIssuerKind),kind)||string.IsNullOrWhiteSpace(id))return false;switch((ContractIssuerKind)kind){case ContractIssuerKind.Character:return characters.Contains(id);case ContractIssuerKind.City:return cities.Contains(id);case ContractIssuerKind.Faction:return factions.Contains(id);case ContractIssuerKind.Clique:return cliques.Contains(id);case ContractIssuerKind.Organization:return organizations.Contains(id);default:return false;}}
        private static bool SavedTargetValid(int kind,string id,HashSet<string> characters,HashSet<string> cities,HashSet<string> caravans,HashSet<string> factions,HashSet<string> cliques,HashSet<string> armies,HashSet<string> battles,HashSet<string> encounters){if(!Enum.IsDefined(typeof(ContractTargetKind),kind)||string.IsNullOrWhiteSpace(id))return false;switch((ContractTargetKind)kind){case ContractTargetKind.Character:return characters.Contains(id);case ContractTargetKind.City:return cities.Contains(id);case ContractTargetKind.Caravan:return caravans.Contains(id);case ContractTargetKind.Faction:return factions.Contains(id);case ContractTargetKind.Clique:return cliques.Contains(id);case ContractTargetKind.Army:return armies.Contains(id);case ContractTargetKind.Battle:return battles.Contains(id);case ContractTargetKind.Encounter:return encounters.Contains(id);default:return false;}}

        private static void ValidateSoldiers(CampaignSaveData s,ValidationResult r)
        {
            var goods=new HashSet<string>(s.TradeGoods.Where(x=>x!=null).Select(x=>x.TradeGoodId),StringComparer.Ordinal);var cities=new HashSet<string>(s.Cities.Where(x=>x!=null).Select(x=>x.CityId),StringComparer.Ordinal);var units=new Dictionary<string,UnitGroupSaveData>(StringComparer.Ordinal);foreach(var a in s.Armies)if(a!=null)foreach(var u in a.Units)if(u!=null&&!units.ContainsKey(u.UnitGroupId))units.Add(u.UnitGroupId,u);var records=new Dictionary<string,RecruitmentRecordSaveData>(StringComparer.Ordinal);foreach(var x in s.RecruitmentRecords)if(x!=null&&!records.ContainsKey(x.RecruitmentRecordId))records.Add(x.RecruitmentRecordId,x);
            var troops=new Dictionary<string,TroopDefinitionSaveData>(StringComparer.Ordinal);foreach(var x in s.TroopDefinitions){if(x==null||string.IsNullOrWhiteSpace(x.TroopDefinitionId)||string.IsNullOrWhiteSpace(x.Name)||string.IsNullOrWhiteSpace(x.UnitClassId)||string.IsNullOrWhiteSpace(x.DefaultCombatRoleId)||string.IsNullOrWhiteSpace(x.VisualProfileId)||!Enum.IsDefined(typeof(MountContext),x.MountContext)||x.AllowedWeaponFamilies==null||x.AllowedWeaponFamilies.Any(v=>!Enum.IsDefined(typeof(WeaponFamily),v))||x.AllowedWeaponFamilies.Distinct().Count()!=x.AllowedWeaponFamilies.Count||troops.ContainsKey(x.TroopDefinitionId)){r.AddError("TROOP_DEFINITION_INVALID","Troop definition is invalid.");continue;}troops.Add(x.TroopDefinitionId,x);}
            var definitions=new Dictionary<string,string>(StringComparer.Ordinal);foreach(var x in s.WeaponDefinitions){var key=((int)EquipmentKind.Weapon)+"\n"+x?.WeaponDefinitionId;if(x==null||string.IsNullOrWhiteSpace(x.WeaponDefinitionId)||string.IsNullOrWhiteSpace(x.Name)||!Enum.IsDefined(typeof(WeaponFamily),x.Family)||!Enum.IsDefined(typeof(MountContext),x.MountContext)||!goods.Contains(x.EconomicGoodId)||string.IsNullOrWhiteSpace(x.VisualProfileId)||x.AllowedSlots==null||x.AllowedSlots.Count==0||x.AllowedSlots.Any(v=>!Enum.IsDefined(typeof(WeaponSlot),v)||v==(int)WeaponSlot.Ammo)||x.AllowedSlots.Distinct().Count()!=x.AllowedSlots.Count||x.AttackOptions==null||x.AttackOptions.Count==0||x.AttackOptions.Any(a=>a==null||!Enum.IsDefined(typeof(AttackMode),a.Mode)||!Enum.IsDefined(typeof(DamageType),a.DamageType))||x.IsRanged!=!string.IsNullOrEmpty(x.AmmoFamilyId)||definitions.ContainsKey(key)){r.AddError("WEAPON_DEFINITION_INVALID","Weapon definition is invalid.");continue;}definitions.Add(key,x.EconomicGoodId);}foreach(var x in s.ArmorDefinitions){var key=((int)EquipmentKind.Armor)+"\n"+x?.ArmorDefinitionId;if(x==null||string.IsNullOrWhiteSpace(x.ArmorDefinitionId)||string.IsNullOrWhiteSpace(x.Name)||!Enum.IsDefined(typeof(ArmorSlot),x.Slot)||!goods.Contains(x.EconomicGoodId)||string.IsNullOrWhiteSpace(x.VisualProfileId)||string.IsNullOrWhiteSpace(x.QualityCode)||definitions.ContainsKey(key)){r.AddError("ARMOR_DEFINITION_INVALID","Armor definition is invalid.");continue;}definitions.Add(key,x.EconomicGoodId);}foreach(var x in s.ShieldDefinitions){var key=((int)EquipmentKind.Shield)+"\n"+x?.ShieldDefinitionId;if(x==null||string.IsNullOrWhiteSpace(x.ShieldDefinitionId)||string.IsNullOrWhiteSpace(x.Name)||!goods.Contains(x.EconomicGoodId)||string.IsNullOrWhiteSpace(x.VisualProfileId)||string.IsNullOrWhiteSpace(x.Classification)||definitions.ContainsKey(key)){r.AddError("SHIELD_DEFINITION_INVALID","Shield definition is invalid.");continue;}definitions.Add(key,x.EconomicGoodId);}foreach(var x in s.MountDefinitions){var key=((int)EquipmentKind.Mount)+"\n"+x?.MountDefinitionId;if(x==null||string.IsNullOrWhiteSpace(x.MountDefinitionId)||string.IsNullOrWhiteSpace(x.Name)||!goods.Contains(x.EconomicGoodId)||string.IsNullOrWhiteSpace(x.VisualProfileId)||string.IsNullOrWhiteSpace(x.MobilityClass)||definitions.ContainsKey(key)){r.AddError("MOUNT_DEFINITION_INVALID","Mount definition is invalid.");continue;}definitions.Add(key,x.EconomicGoodId);}foreach(var x in s.AuxiliaryEquipmentDefinitions){var key=((int)EquipmentKind.Auxiliary)+"\n"+x?.AuxiliaryEquipmentDefinitionId;if(x==null||string.IsNullOrWhiteSpace(x.AuxiliaryEquipmentDefinitionId)||string.IsNullOrWhiteSpace(x.Name)||!Enum.IsDefined(typeof(AuxiliaryEquipmentKind),x.Kind)||!goods.Contains(x.EconomicGoodId)||string.IsNullOrWhiteSpace(x.VisualProfileId)||(x.Kind==(int)AuxiliaryEquipmentKind.Ammunition)!=!string.IsNullOrEmpty(x.AmmoFamilyId)||definitions.ContainsKey(key)){r.AddError("AUXILIARY_DEFINITION_INVALID","Auxiliary definition is invalid.");continue;}definitions.Add(key,x.EconomicGoodId);}
            var soldierIds=new HashSet<string>(StringComparer.Ordinal);foreach(var x in s.Soldiers)if(x==null||string.IsNullOrWhiteSpace(x.SoldierId)||!soldierIds.Add(x.SoldierId))r.AddError("SOLDIER_ID_INVALID","Soldier IDs must be unique and complete.");var equipment=new Dictionary<string,EquipmentInstanceSaveData>(StringComparer.Ordinal);foreach(var x in s.EquipmentInstances){var key=x==null?string.Empty:x.DefinitionKind+"\n"+x.DefinitionId;if(x==null||string.IsNullOrWhiteSpace(x.EquipmentInstanceId)||equipment.ContainsKey(x.EquipmentInstanceId)||!Enum.IsDefined(typeof(EquipmentKind),x.DefinitionKind)||!definitions.TryGetValue(key,out var mappedGood)||!StringComparer.Ordinal.Equals(mappedGood,x.EconomicGoodId)||!Enum.IsDefined(typeof(EquipmentOwnerKind),x.OwnerKind)||string.IsNullOrWhiteSpace(x.OwnerId)||(x.OwnerKind==(int)EquipmentOwnerKind.Soldier&&!soldierIds.Contains(x.OwnerId))||!Enum.IsDefined(typeof(EquipmentAcquisitionKind),x.AcquisitionKind)||x.AcquiredAt<0||string.IsNullOrWhiteSpace(x.QualityCode)||(x.AcquisitionKind==(int)EquipmentAcquisitionKind.CityMarket&&!cities.Contains(x.AcquisitionSourceId))||(x.AcquisitionKind==(int)EquipmentAcquisitionKind.RecruitmentProvided&&!records.ContainsKey(x.AcquisitionSourceId))){r.AddError("EQUIPMENT_INSTANCE_INVALID","Equipment instance is invalid.");continue;}equipment.Add(x.EquipmentInstanceId,x);}
            var groupCounts=new Dictionary<string,long>(StringComparer.Ordinal);foreach(var x in s.Soldiers){if(x==null)continue;if(!units.TryGetValue(x.UnitGroupId,out var unit)||!troops.ContainsKey(x.TroopDefinitionId)||!StringComparer.Ordinal.Equals(unit?.TroopDefinitionId,x.TroopDefinitionId)||!records.TryGetValue(x.RecruitmentRecordId,out var record)||!StringComparer.Ordinal.Equals(record?.RecruitmentSourceId,x.RecruitmentSourceId)||!StringComparer.Ordinal.Equals(record?.UnitGroupId,x.UnitGroupId)||string.IsNullOrWhiteSpace(x.CombatRoleId)||!Enum.IsDefined(typeof(SoldierExperienceAssessment),x.Experience)||!Enum.IsDefined(typeof(SoldierTrainingAssessment),x.Training)||!Enum.IsDefined(typeof(SoldierLifecycle),x.Lifecycle)||x.Weapons==null||x.Armor==null){r.AddError("SOLDIER_INVALID","Soldier state or provenance is invalid.");continue;}if(x.Lifecycle!=(int)SoldierLifecycle.Retired&&x.Lifecycle!=(int)SoldierLifecycle.Killed&&x.Lifecycle!=(int)SoldierLifecycle.Captured)groupCounts[x.UnitGroupId]=(groupCounts.TryGetValue(x.UnitGroupId,out var n)?n:0)+1;var used=new HashSet<string>(StringComparer.Ordinal);var weaponSlots=new HashSet<int>();foreach(var q in x.Weapons)if(q==null||!Enum.IsDefined(typeof(WeaponSlot),q.Slot)||!weaponSlots.Add(q.Slot)||!LoadoutOwner(equipment,q.EquipmentInstanceId,x.SoldierId)||!used.Add(q.EquipmentInstanceId))r.AddError("SOLDIER_WEAPON_SLOT_INVALID","Soldier weapon slot is invalid.");var armorSlots=new HashSet<int>();foreach(var q in x.Armor)if(q==null||!Enum.IsDefined(typeof(ArmorSlot),q.Slot)||!armorSlots.Add(q.Slot)||!LoadoutOwner(equipment,q.EquipmentInstanceId,x.SoldierId)||!used.Add(q.EquipmentInstanceId))r.AddError("SOLDIER_ARMOR_SLOT_INVALID","Soldier armor slot is invalid.");foreach(var id in new[]{x.ShieldEquipmentId,x.MountEquipmentId})if(!string.IsNullOrEmpty(id)&&(!LoadoutOwner(equipment,id,x.SoldierId)||!used.Add(id)))r.AddError("SOLDIER_LOADOUT_INVALID","Soldier loadout reference is invalid.");ValidateSavedLoadoutCompatibility(s,x,troops[x.TroopDefinitionId],equipment,r);}foreach(var pair in groupCounts)if(units.TryGetValue(pair.Key,out var unit)&&pair.Value>unit.Headcount)r.AddError("SOLDIER_HEADCOUNT_EXCEEDED","Instantiated Soldiers exceed Unit Group headcount.");
        }
        private static bool LoadoutOwner(Dictionary<string,EquipmentInstanceSaveData> equipment,string id,string soldierId)=>equipment.TryGetValue(id,out var x)&&x.OwnerKind==(int)EquipmentOwnerKind.Soldier&&StringComparer.Ordinal.Equals(x.OwnerId,soldierId);
        private static void ValidateSavedLoadoutCompatibility(CampaignSaveData s,SoldierSaveData soldier,TroopDefinitionSaveData troop,Dictionary<string,EquipmentInstanceSaveData> equipment,ValidationResult r)
        {
            var mounted=!string.IsNullOrEmpty(soldier.MountEquipmentId);if(troop.MountContext==(int)MountContext.MountedOnly&&!mounted||troop.MountContext==(int)MountContext.InfantryOnly&&mounted)r.AddError("SOLDIER_MOUNT_INCOMPATIBLE","Soldier mount conflicts with troop definition.");if(!troop.AllowsArmor&&soldier.Armor.Count>0)r.AddError("SOLDIER_ARMOR_FORBIDDEN","Troop definition does not allow armor.");if(!troop.AllowsShield&&!string.IsNullOrEmpty(soldier.ShieldEquipmentId))r.AddError("SOLDIER_SHIELD_FORBIDDEN","Troop definition does not allow shield.");
            foreach(var slot in soldier.Weapons){if(slot==null||!equipment.TryGetValue(slot.EquipmentInstanceId,out var item))continue;if(item.DefinitionKind==(int)EquipmentKind.Weapon){var definition=s.WeaponDefinitions.FirstOrDefault(x=>x!=null&&StringComparer.Ordinal.Equals(x.WeaponDefinitionId,item.DefinitionId));if(definition==null||!definition.AllowedSlots.Contains(slot.Slot)||(troop.AllowedWeaponFamilies.Count>0&&!troop.AllowedWeaponFamilies.Contains(definition.Family))||(definition.MountContext==(int)MountContext.MountedOnly&&!mounted)||(definition.MountContext==(int)MountContext.InfantryOnly&&mounted)){r.AddError("SOLDIER_WEAPON_COMPATIBILITY_INVALID","Weapon is incompatible with Soldier loadout.");continue;}if(definition.IsRanged){var ammoSlot=soldier.Weapons.FirstOrDefault(x=>x!=null&&x.Slot==(int)WeaponSlot.Ammo);if(ammoSlot==null||!equipment.TryGetValue(ammoSlot.EquipmentInstanceId,out var ammoItem)||ammoItem.DefinitionKind!=(int)EquipmentKind.Auxiliary){r.AddError("SOLDIER_AMMO_COMPATIBILITY_INVALID","Ranged weapon ammunition is missing.");continue;}var ammo=s.AuxiliaryEquipmentDefinitions.FirstOrDefault(x=>x!=null&&StringComparer.Ordinal.Equals(x.AuxiliaryEquipmentDefinitionId,ammoItem.DefinitionId));if(ammo==null||ammo.Kind!=(int)AuxiliaryEquipmentKind.Ammunition||!StringComparer.Ordinal.Equals(ammo.AmmoFamilyId,definition.AmmoFamilyId))r.AddError("SOLDIER_AMMO_COMPATIBILITY_INVALID","Ranged weapon ammunition is incompatible.");}}else if(item.DefinitionKind==(int)EquipmentKind.Auxiliary){var aux=s.AuxiliaryEquipmentDefinitions.FirstOrDefault(x=>x!=null&&StringComparer.Ordinal.Equals(x.AuxiliaryEquipmentDefinitionId,item.DefinitionId));if(aux==null||(aux.Kind==(int)AuxiliaryEquipmentKind.Ammunition)!=(slot.Slot==(int)WeaponSlot.Ammo)||(aux.Kind==(int)AuxiliaryEquipmentKind.Special)!=(slot.Slot==(int)WeaponSlot.Special))r.AddError("SOLDIER_AUXILIARY_SLOT_INVALID","Auxiliary equipment slot is incompatible.");}else r.AddError("SOLDIER_WEAPON_COMPATIBILITY_INVALID","Non-weapon equipment occupies weapon slot.");}
            foreach(var slot in soldier.Armor){if(slot==null||!equipment.TryGetValue(slot.EquipmentInstanceId,out var item))continue;var definition=s.ArmorDefinitions.FirstOrDefault(x=>x!=null&&StringComparer.Ordinal.Equals(x.ArmorDefinitionId,item.DefinitionId));if(item.DefinitionKind!=(int)EquipmentKind.Armor||definition==null||definition.Slot!=slot.Slot||(slot.Slot==(int)ArmorSlot.MountArmor&&!mounted))r.AddError("SOLDIER_ARMOR_COMPATIBILITY_INVALID","Armor slot is incompatible.");}if(!string.IsNullOrEmpty(soldier.ShieldEquipmentId)&&equipment.TryGetValue(soldier.ShieldEquipmentId,out var shield)&&shield.DefinitionKind!=(int)EquipmentKind.Shield)r.AddError("SOLDIER_SHIELD_COMPATIBILITY_INVALID","Shield slot is incompatible.");if(!string.IsNullOrEmpty(soldier.MountEquipmentId)&&equipment.TryGetValue(soldier.MountEquipmentId,out var mount)&&mount.DefinitionKind!=(int)EquipmentKind.Mount)r.AddError("SOLDIER_MOUNT_COMPATIBILITY_INVALID","Mount slot is incompatible.");
        }

        private static void ValidateMilitary(CampaignSaveData s,ValidationResult r)
        {
            var characters=new Dictionary<string,CharacterSaveData>(StringComparer.Ordinal);foreach(var x in s.Characters)if(x!=null&&!characters.ContainsKey(x.CharacterId))characters.Add(x.CharacterId,x);var organizations=new HashSet<string>(s.Organizations.Where(x=>x!=null).Select(x=>x.OrganizationId),StringComparer.Ordinal);var cities=new HashSet<string>(s.Cities.Where(x=>x!=null).Select(x=>x.CityId),StringComparer.Ordinal);var markets=new HashSet<string>(s.CityMarkets.Where(x=>x!=null).Select(x=>x.CityId),StringComparer.Ordinal);var caravans=new HashSet<string>(s.Caravans.Where(x=>x!=null).Select(x=>x.CaravanId),StringComparer.Ordinal);var factions=new HashSet<string>(s.DiplomaticActors.Where(x=>x!=null).Select(x=>x.FactionId),StringComparer.Ordinal);var goods=new Dictionary<string,TradeGoodSaveData>(StringComparer.Ordinal);foreach(var g in s.TradeGoods)if(g!=null&&!goods.ContainsKey(g.TradeGoodId))goods.Add(g.TradeGoodId,g);
            var sources=new Dictionary<string,RecruitmentSourceSaveData>(StringComparer.Ordinal);foreach(var x in s.RecruitmentSources){if(x==null||string.IsNullOrWhiteSpace(x.RecruitmentSourceId)||sources.ContainsKey(x.RecruitmentSourceId)||!Enum.IsDefined(typeof(RecruitmentType),x.Type)||x.AvailableHeadcount<0||!RecruitmentAuthorityExists(s,x)||(x.IsActive&&!RecruitmentAuthorityValid(s,x))||(!string.IsNullOrEmpty(x.CityId)&&!cities.Contains(x.CityId))||(!string.IsNullOrEmpty(x.InstitutionId)&&!ActiveMilitaryBuilding(s,x.CityId,x.InstitutionId))||((x.Type==(int)RecruitmentType.TimarService||x.Type==(int)RecruitmentType.Mercenary)&&string.IsNullOrWhiteSpace(x.ObligationOrContractId))||(x.Type==(int)RecruitmentType.Garrison&&string.IsNullOrEmpty(x.CityId))){r.AddError("RECRUITMENT_SOURCE_INVALID","Recruitment source is invalid.");continue;}sources.Add(x.RecruitmentSourceId,x);}
            var armies=new Dictionary<string,ArmySaveData>(StringComparer.Ordinal);var allUnits=new HashSet<string>(StringComparer.Ordinal);foreach(var x in s.Armies){if(x==null||string.IsNullOrWhiteSpace(x.ArmyId)||string.IsNullOrWhiteSpace(x.Name)||armies.ContainsKey(x.ArmyId)||!Enum.IsDefined(typeof(ArmyOwnerKind),x.OwnerKind)||!ArmyOwnerValid(s,x.OwnerKind,x.OwnerId,characters,organizations,cities,caravans,factions)||!Enum.IsDefined(typeof(ArmyOwnerKind),x.ControllerKind)||!ArmyOwnerValid(s,x.ControllerKind,x.ControllerId,characters,organizations,cities,caravans,factions)||!Enum.IsDefined(typeof(ArmyLocationKind),x.LocationKind)||(x.LocationKind==(int)ArmyLocationKind.City&&!cities.Contains(x.CityId))||!Enum.IsDefined(typeof(ArmyLifecycle),x.Lifecycle)||!Enum.IsDefined(typeof(MoraleAssessment),x.Morale)||!Enum.IsDefined(typeof(FatigueAssessment),x.Fatigue)||!Enum.IsDefined(typeof(DisciplineAssessment),x.Discipline)||x.Units==null||x.CommandRelationships==null||x.Supply==null||x.SupplyRequirements==null||x.PayrollObligations==null||x.PayrollPayments==null||!ArmyCommanderValid(s,x,characters)){r.AddError("ARMY_INVALID","Army is invalid.");continue;}armies.Add(x.ArmyId,x);var unitIds=new HashSet<string>(StringComparer.Ordinal);foreach(var u in x.Units)if(u==null||string.IsNullOrWhiteSpace(u.UnitGroupId)||!unitIds.Add(u.UnitGroupId)||!allUnits.Add(u.UnitGroupId)||!sources.ContainsKey(u.RecruitmentSourceId)||string.IsNullOrWhiteSpace(u.TroopDefinitionId)||u.Headcount<0||!Enum.IsDefined(typeof(MoraleAssessment),u.Morale)||!Enum.IsDefined(typeof(FatigueAssessment),u.Fatigue)||!Enum.IsDefined(typeof(DisciplineAssessment),u.Discipline)||(!string.IsNullOrEmpty(u.CommanderCharacterId)&&(!characters.TryGetValue(u.CommanderCharacterId,out var uc)||uc.Death!=null||uc.Location.Kind==(int)CharacterLocationKind.Captivity)))r.AddError("UNIT_GROUP_INVALID","Unit Group is invalid.");ValidateCommandHierarchy(x,unitIds,r);var supplyGoods=new HashSet<string>(StringComparer.Ordinal);foreach(var q in x.Supply)if(q==null||!goods.ContainsKey(q.TradeGoodId)||q.Quantity<0||!supplyGoods.Add(q.TradeGoodId))r.AddError("ARMY_SUPPLY_INVALID","Army supply is invalid.");var requirementGoods=new HashSet<string>(StringComparer.Ordinal);foreach(var q in x.SupplyRequirements)if(q==null||!goods.TryGetValue(q.TradeGoodId,out var good)||!Enum.IsDefined(typeof(SupplyPurpose),q.Purpose)||q.RequiredQuantity<0||!requirementGoods.Add(q.TradeGoodId)||(q.Purpose==(int)SupplyPurpose.Food&&!good.IsFood)||(q.Purpose==(int)SupplyPurpose.Ammunition&&!good.IsMilitaryGood))r.AddError("ARMY_SUPPLY_REQUIREMENT_INVALID","Army supply requirement is invalid.");ValidatePayroll(x,markets,caravans,r);}
            var records=new HashSet<string>(StringComparer.Ordinal);foreach(var x in s.RecruitmentRecords)if(x==null||string.IsNullOrWhiteSpace(x.RecruitmentRecordId)||!records.Add(x.RecruitmentRecordId)||!sources.ContainsKey(x.RecruitmentSourceId)||!armies.TryGetValue(x.ArmyId,out var army)||!army.Units.Any(u=>u!=null&&StringComparer.Ordinal.Equals(u.UnitGroupId,x.UnitGroupId))||x.Headcount<=0||x.OccurredAt<0)r.AddError("RECRUITMENT_RECORD_INVALID","Recruitment record is invalid.");
        }
        private static bool RecruitmentAuthorityValid(CampaignSaveData s,RecruitmentSourceSaveData x){if(string.IsNullOrWhiteSpace(x.AuthorityCharacterId)||string.IsNullOrWhiteSpace(x.AuthorityOrganizationId)||string.IsNullOrWhiteSpace(x.AuthorityAssignmentId))return false;foreach(var o in s.Organizations)if(o!=null&&StringComparer.Ordinal.Equals(o.OrganizationId,x.AuthorityOrganizationId))foreach(var a in o.Assignments)if(a!=null&&StringComparer.Ordinal.Equals(a.AssignmentId,x.AuthorityAssignmentId)&&StringComparer.Ordinal.Equals(a.CharacterId,x.AuthorityCharacterId)&&a.Branch==(int)OrganizationBranch.Army&&a.Status==(int)AssignmentStatus.Active)return true;return false;}
        private static bool RecruitmentAuthorityExists(CampaignSaveData s,RecruitmentSourceSaveData x){if(string.IsNullOrWhiteSpace(x.AuthorityCharacterId)||string.IsNullOrWhiteSpace(x.AuthorityOrganizationId)||string.IsNullOrWhiteSpace(x.AuthorityAssignmentId)||!s.Characters.Any(c=>c!=null&&StringComparer.Ordinal.Equals(c.CharacterId,x.AuthorityCharacterId)))return false;foreach(var o in s.Organizations)if(o!=null&&StringComparer.Ordinal.Equals(o.OrganizationId,x.AuthorityOrganizationId))foreach(var a in o.Assignments)if(a!=null&&StringComparer.Ordinal.Equals(a.AssignmentId,x.AuthorityAssignmentId)&&StringComparer.Ordinal.Equals(a.CharacterId,x.AuthorityCharacterId)&&a.Branch==(int)OrganizationBranch.Army)return true;return false;}
        private static bool ActiveMilitaryBuilding(CampaignSaveData s,string cityId,string buildingId){if(string.IsNullOrEmpty(cityId)||string.IsNullOrEmpty(buildingId))return false;foreach(var c in s.Cities)if(c!=null&&StringComparer.Ordinal.Equals(c.CityId,cityId))foreach(var a in c.Areas)if(a!=null&&a.Type==(int)CityAreaType.Military&&a.ActiveBuildingIds.Contains(buildingId)&&a.BuildingPool.Any(b=>b!=null&&StringComparer.Ordinal.Equals(b.CityBuildingId,buildingId)&&b.Status==(int)CityBuildingContentStatus.Active))return true;return false;}
        private static bool ArmyOwnerValid(CampaignSaveData s,int kind,string id,Dictionary<string,CharacterSaveData> characters,HashSet<string> organizations,HashSet<string> cities,HashSet<string> caravans,HashSet<string> factions){if(string.IsNullOrWhiteSpace(id))return false;switch((ArmyOwnerKind)kind){case ArmyOwnerKind.Character:return characters.ContainsKey(id);case ArmyOwnerKind.Faction:return factions.Contains(id);case ArmyOwnerKind.Organization:return organizations.Contains(id);case ArmyOwnerKind.CityGarrison:return cities.Contains(id);case ArmyOwnerKind.Institution:return s.Cities.Any(c=>c!=null&&c.Areas.Any(a=>a!=null&&a.Type==(int)CityAreaType.Military&&a.ActiveBuildingIds.Contains(id)));case ArmyOwnerKind.MercenaryCompany:return true;case ArmyOwnerKind.CaravanSecurity:return caravans.Contains(id);default:return false;}}
        private static bool ArmyCommanderValid(CampaignSaveData s,ArmySaveData x,Dictionary<string,CharacterSaveData> characters){var any=!(string.IsNullOrEmpty(x.CommanderCharacterId)&&string.IsNullOrEmpty(x.CommanderOrganizationId)&&string.IsNullOrEmpty(x.CommanderAssignmentId));if(!any)return true;if(string.IsNullOrEmpty(x.CommanderCharacterId)||string.IsNullOrEmpty(x.CommanderOrganizationId)||string.IsNullOrEmpty(x.CommanderAssignmentId)||!characters.TryGetValue(x.CommanderCharacterId,out var character)||character.Death!=null||character.Location.Kind==(int)CharacterLocationKind.Captivity)return false;foreach(var o in s.Organizations)if(o!=null&&StringComparer.Ordinal.Equals(o.OrganizationId,x.CommanderOrganizationId))foreach(var a in o.Assignments)if(a!=null&&StringComparer.Ordinal.Equals(a.AssignmentId,x.CommanderAssignmentId)&&StringComparer.Ordinal.Equals(a.CharacterId,x.CommanderCharacterId)&&a.Branch==(int)OrganizationBranch.Army&&a.TargetKind==(int)AssignmentTargetKind.Army&&StringComparer.Ordinal.Equals(a.TargetId,x.ArmyId)&&a.Status==(int)AssignmentStatus.Active)return true;return false;}
        private static void ValidateCommandHierarchy(ArmySaveData x,HashSet<string> unitIds,ValidationResult r){var hierarchy=new CommandHierarchy(ArmyId.Create(x.ArmyId));try{foreach(var c in x.CommandRelationships){if(c==null||!Enum.IsDefined(typeof(CommandNodeKind),c.ParentKind)||!Enum.IsDefined(typeof(CommandNodeKind),c.ChildKind)||!NodeValid(c.ParentKind,c.ParentId,x.ArmyId,unitIds)||!NodeValid(c.ChildKind,c.ChildId,x.ArmyId,unitIds))throw new InvalidOperationException();hierarchy.Add(new CommandRelationship(ToNode(c.ParentKind,c.ParentId),ToNode(c.ChildKind,c.ChildId)));}}catch(Exception){r.AddError("COMMAND_HIERARCHY_INVALID","Command hierarchy is invalid.");}}
        private static bool NodeValid(int kind,string id,string armyId,HashSet<string> units)=>kind==(int)CommandNodeKind.Army?StringComparer.Ordinal.Equals(id,armyId):kind==(int)CommandNodeKind.UnitGroup&&units.Contains(id);private static CommandNodeRef ToNode(int kind,string id)=>kind==(int)CommandNodeKind.Army?CommandNodeRef.Army(ArmyId.Create(id)):CommandNodeRef.Unit(UnitGroupId.Create(id));
        private static void ValidatePayroll(ArmySaveData x,HashSet<string> markets,HashSet<string> caravans,ValidationResult r){var obligations=new Dictionary<string,PayrollObligationSaveData>(StringComparer.Ordinal);foreach(var o in x.PayrollObligations){if(o==null||string.IsNullOrWhiteSpace(o.PayrollObligationId)||obligations.ContainsKey(o.PayrollObligationId)||o.AmountOwed<=0||o.AmountPaid<0||o.AmountPaid>o.AmountOwed||o.DueAt<0||!FundingValid(o.FundingSourceKind,o.FundingSourceId,markets,caravans)){r.AddError("PAYROLL_OBLIGATION_INVALID","Payroll obligation is invalid.");continue;}obligations.Add(o.PayrollObligationId,o);}var payments=new HashSet<string>(StringComparer.Ordinal);var paid=new Dictionary<string,long>(StringComparer.Ordinal);foreach(var p in x.PayrollPayments){if(p==null||string.IsNullOrWhiteSpace(p.PayrollPaymentId)||!payments.Add(p.PayrollPaymentId)||p.Amount<=0||p.PaidAt<0||!obligations.TryGetValue(p.PayrollObligationId,out var o)||p.FundingSourceKind!=o.FundingSourceKind||!StringComparer.Ordinal.Equals(p.FundingSourceId,o.FundingSourceId)){r.AddError("PAYROLL_PAYMENT_INVALID","Payroll payment is invalid.");continue;}try{paid[p.PayrollObligationId]=checked((paid.TryGetValue(p.PayrollObligationId,out var current)?current:0)+p.Amount);}catch(OverflowException){r.AddError("PAYROLL_PAYMENT_INVALID","Payroll payment overflowed.");}}foreach(var pair in obligations)if((paid.TryGetValue(pair.Key,out var total)?total:0)!=pair.Value.AmountPaid)r.AddError("PAYROLL_RECONCILIATION_INVALID","Payroll paid amount does not match payment history.");}
        private static bool FundingValid(int kind,string id,HashSet<string> markets,HashSet<string> caravans)=>kind==(int)PayrollFundingSourceKind.CityMarket?markets.Contains(id):kind==(int)PayrollFundingSourceKind.Caravan&&caravans.Contains(id);

        private static void ValidateDiplomacy(CampaignSaveData s,ValidationResult r)
